CREATE COLUMN TABLE "TEST_AP"."OIVK" ("TransSeq" INTEGER CS_INT NOT NULL , "LayerID" INTEGER CS_INT NOT NULL , "RootID" INTEGER CS_INT, "TransNum" INTEGER CS_INT, "Instance" INTEGER CS_INT DEFAULT 0, "INMTransSe" INTEGER CS_INT NOT NULL , PRIMARY KEY ("INMTransSe")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OIVK_TRANSSEQ" ON "TEST_AP"."OIVK" ( "TransSeq" ASC, "LayerID" ASC )